<x-app-layout>
    <x-slot name="header"><div><span class="text-[10px] font-bold uppercase tracking-[.18em] text-violet-500">DAYWELL WORKSPACE</span><h1 class="mt-1 text-xl font-bold text-slate-800">Routine & reflection</h1></div></x-slot>
    <div x-data="routineDashboard()" x-init="init()" @keydown.escape.window="report=null;selectedUser=null" class="routine-shell">
        <aside class="routine-sidebar" :class="mobileNav?'routine-sidebar-open':''">
            <div class="mb-8 flex items-center gap-2 px-2 text-xl font-extrabold tracking-tight"> <span class="grid h-8 w-8 place-items-center rounded-xl bg-violet-500 text-white">✳</span> daywell<span class="-ml-2 text-violet-500">.</span><button class="ml-auto md:hidden" @click="mobileNav=false">✕</button></div>
            <small class="mb-2 px-2 text-[9px] font-bold tracking-widest text-slate-400">WORKSPACE</small>
            <nav class="space-y-1">
                <button x-show="admin" @click="section='overview';mobileNav=false" :class="section==='overview'?'routine-active':''" class="routine-nav">▦ <span>Overview</span></button>
                <button x-show="admin" @click="section='people';mobileNav=false" :class="section==='people'?'routine-active':''" class="routine-nav">♙ <span>People</span></button>
                <button x-show="admin" @click="section='groups';mobileNav=false" :class="section==='groups'?'routine-active':''" class="routine-nav">♧ <span>Groups</span></button>
                <button @click="section='assessment';mobileNav=false" :class="section==='assessment'?'routine-active':''" class="routine-nav">◷ <span>Daily reflection</span></button>
                <button x-show="admin" @click="section='review';loadReports();mobileNav=false" :class="section==='review'?'routine-active':''" class="routine-nav">▤ <span>Report review</span><b x-show="stats.pending_reviews" class="ml-auto rounded-full bg-white px-2 text-[10px]" x-text="stats.pending_reviews"></b></button>
            </nav>
            <div class="routine-quote"><span>✦</span><p>Small, consistent steps make meaningful days.</p><small>YOUR DAILY REMINDER</small></div>
            <div class="mt-auto flex items-center gap-2 border-t border-slate-100 pt-4"><span class="routine-avatar" x-text="user?.name?.slice(0,1)?.toUpperCase()||'U'"></span><span class="min-w-0"><b class="block truncate text-xs" x-text="user?.name||'Your account'"></b><small class="block truncate text-[10px] text-slate-400" x-text="user?.email||''"></small></span></div>
        </aside>
        <button x-show="mobileNav" class="routine-scrim md:hidden" @click="mobileNav=false"></button>
        <main class="min-w-0 flex-1">
            <div class="routine-top"><button class="md:hidden" @click="mobileNav=true">☰</button><span>Workspace <i>/</i> <b x-text="({overview:'Overview',people:'People',groups:'Groups',assessment:'Daily reflection',review:'Report review'})[section]"></b></span><span class="routine-avatar ml-auto" x-text="user?.name?.slice(0,1)?.toUpperCase()||'U'"></span></div>
            <div class="routine-content">
                <div x-show="error" x-cloak class="mb-4 flex justify-between rounded-lg border border-rose-200 bg-rose-50 px-4 py-3 text-xs text-rose-700"><span x-text="error"></span><button @click="error=''">✕</button></div>
                <div x-show="loading" class="flex min-h-64 items-center justify-center gap-3 text-sm text-slate-500"><span class="routine-spinner"></span> Loading your workspace…</div>
                <div x-show="!loading">
                    <section x-show="section==='overview'&&admin">
                        <div class="routine-heading"><div><small class="routine-eyebrow">YOUR CONTROL CENTER</small><h2>Good day, <span x-text="user?.name?.split(' ')[0]||'Admin'"></span></h2><p>A clear view of your community and daily progress.</p></div><button class="routine-primary" @click="section='review';loadReports()">▤ Review reports</button></div>
                        <div class="routine-stats"><template x-for="card in [{k:'Registered people',v:stats.users,c:'violet',s:'Across your workspace'},{k:'Active groups',v:stats.groups,c:'green',s:'Communities & teams'},{k:'Reports today',v:stats.reports_today,c:'peach',s:'Daily reflections'},{k:'Awaiting review',v:stats.pending_reviews,c:'blue',s:'Ready for feedback'}]" :key="card.k"><article class="routine-stat"><span class="routine-icon" :class="`tone-${card.c}`">✦</span><small x-text="card.k"></small><b x-text="card.v"></b><em x-text="card.s"></em></article></template></div>
                        <div class="grid gap-4 xl:grid-cols-[1.5fr_1fr]"><section class="routine-panel"><header class="routine-panel-head"><div><h3>Recent people</h3><p>Members who recently joined</p></div><button class="routine-link" @click="section='people'">View all ↗</button></header><div class="overflow-x-auto"><table class="routine-table"><thead><tr><th>PERSON</th><th>EMAIL</th><th>STATUS</th></tr></thead><tbody><template x-for="person in users.slice(0,6)" :key="person.id"><tr><td><b x-text="person.name"></b></td><td x-text="person.email"></td><td><span class="routine-status" x-text="person.status||'active'"></span></td></tr></template><tr x-show="!users.length"><td colspan="3" class="text-center text-slate-400">No people found.</td></tr></tbody></table></div></section><section class="routine-panel flex flex-col"><header class="routine-panel-head"><div><h3>Daily momentum</h3><p>Today's community activity</p></div><span class="routine-icon tone-violet">◴</span></header><strong class="mt-3 text-3xl" x-text="stats.reports_today"></strong><small class="text-slate-400">reports submitted today</small><div class="mt-4 h-2 rounded-full bg-slate-100"><div class="h-2 rounded-full bg-violet-400" :style="`width:${stats.users?Math.min(100,stats.reports_today/stats.users*100):0}%`"></div></div><p class="mt-auto rounded-lg bg-violet-50 p-3 text-xs text-violet-800">✦ Thoughtful feedback helps everyone build better routines.</p></section></div>
                        <section class="routine-panel mt-4"><header class="routine-panel-head"><div><h3>Latest daily reports</h3><p>Recent reflections from your community</p></div><button class="routine-link" @click="section='review';loadReports()">Open review ↗</button></header><template x-for="item in reports.slice(0,5)" :key="item.id"><button @click="section='review';openReport(item.id)" class="flex w-full items-center gap-3 border-t border-slate-100 py-3 text-left"><span class="routine-icon tone-violet">▤</span><span class="flex-1"><b class="block text-xs" x-text="item.user?.name||'Member report'"></b><small class="text-[10px] text-slate-400" x-text="`${new Date(item.report_date).toLocaleDateString()} · ${item.completion_percentage}% complete`"></small></span><span class="routine-status" x-text="item.review_status"></span></button></template><p x-show="!reports.length" class="py-6 text-center text-xs text-slate-400">No reports have been submitted yet.</p></section>
                    </section>

                    <section x-show="section==='people'&&admin"><div class="routine-heading"><div><small class="routine-eyebrow">COMMUNITY</small><h2>People</h2><p>Registered accounts and routine activity.</p></div></div><section class="routine-panel"><header class="routine-panel-head"><div><h3>All people <span class="routine-count" x-text="users.length"></span></h3><p>Account overview and status</p></div><input class="routine-input" placeholder="Search people" @input="document.querySelectorAll('[data-person]').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes($event.target.value.toLowerCase()))"></header><div class="overflow-x-auto"><table class="routine-table"><thead><tr><th>PERSON</th><th>EMAIL</th><th>GROUPS</th><th>STATUS</th><th></th></tr></thead><tbody><template x-for="person in users" :key="person.id"><tr data-person><td x-text="person.name"></td><td x-text="person.email"></td><td x-text="person.groups_count||0"></td><td><span class="routine-status" x-text="person.status||'active'"></span></td><td><button class="routine-link" @click="openUser(person.id)">Activity summary ↗</button></td></tr></template></tbody></table></div></section></section>

                    <section x-show="section==='groups'&&admin"><div class="routine-heading"><div><small class="routine-eyebrow">COMMUNITY</small><h2>Groups</h2><p>Groups and their members across your workspace.</p></div></div><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><template x-for="group in groups" :key="group.id"><article class="routine-panel"><div class="flex items-center justify-between"><span class="routine-icon tone-violet">♧</span><span class="routine-status">Active</span></div><h3 class="mt-4 font-bold" x-text="group.name"></h3><p class="mt-1 text-xs text-slate-400" x-text="group.description||'A shared space for building consistent routines.'"></p><div class="mt-4 border-t border-slate-100 pt-3 text-xs text-slate-500" x-text="`${group.members_count||0} members`"></div><div class="mt-2 flex flex-wrap gap-1"><template x-for="member in group.members||[]" :key="member.id"><span class="rounded-full bg-slate-50 px-2 py-1 text-[10px] text-slate-500" x-text="member.name"></span></template></div></article></template><div x-show="!groups.length" class="routine-panel col-span-full py-8 text-center text-xs text-slate-400">No groups found.</div></div></section>

                    <section x-show="section==='assessment'"><div class="routine-heading"><div><small class="routine-eyebrow">DAILY PRACTICE</small><h2>End your day with intention</h2><p>A thoughtful check-in helps you see what went well and what you learned.</p></div></div><section class="routine-panel mb-4"><header class="routine-panel-head"><div><h3>Today's activities</h3><p>From your personal timetable</p></div><div class="flex items-center gap-2"><span class="routine-ring" :style="`--p:${completion}%`"><b x-text="`${completion}%`"></b></span><small x-text="`${summary.completed_activities||0} of ${summary.total_activities||0} done`"></small></div></header><div class="grid gap-2 sm:grid-cols-2"><template x-for="activity in summary.activities||[]" :key="activity.id"><div class="flex items-center gap-3 rounded-lg border border-slate-100 p-3"><span class="text-emerald-500" x-text="activity.status==='completed'?'✓':'○'"></span><span class="flex-1"><b class="block text-xs" x-text="activity.title"></b><small class="text-[10px] capitalize text-slate-400" x-text="`${activity.type} · ${activity.status}`"></small></span></div></template><p x-show="!summary.activities?.length" class="col-span-full py-6 text-center text-xs text-slate-400">No activities are planned for today. Add them in your timetable.</p></div></section><form @submit.prevent="submitReport()" class="routine-panel"><header class="routine-panel-head"><div><h3>Your reflection</h3><p>A few honest notes are enough.</p></div><span class="routine-icon tone-violet">✦</span></header><div class="grid gap-4 md:grid-cols-2"><label class="routine-field md:col-span-2"><span>Daily work summary</span><textarea rows="3" x-model="form.work_summary" placeholder="What did you focus on today?"></textarea></label><label class="routine-field"><span>Challenges faced</span><textarea rows="3" x-model="form.challenges" placeholder="What felt difficult?"></textarea></label><label class="routine-field"><span>Learning & improvement</span><textarea rows="3" x-model="form.learning" placeholder="What will you carry into tomorrow?"></textarea></label><div class="routine-field md:col-span-2"><span>How would you rate your day?</span><div class="flex items-center gap-1"><template x-for="star in [1,2,3,4,5]" :key="star"><button type="button" @click="form.rating=star" class="text-2xl" :class="form.rating>=star?'text-amber-400':'text-slate-200'">★</button></template><small class="ml-2 text-slate-400" x-text="form.rating?`${form.rating} of 5`:'Choose a rating'"></small></div></div><label class="routine-field md:col-span-2"><span>Personal reflection</span><textarea rows="3" x-model="form.reflection" placeholder="Anything else you want to remember about today?"></textarea></label></div><div class="mt-5 flex flex-col gap-3 border-t border-slate-100 pt-4 sm:flex-row sm:items-center sm:justify-between"><small class="text-[10px] text-slate-400">Your reflection is shared with administrators for review.</small><button class="routine-primary" type="submit" :disabled="saving||!form.rating" x-text="saving?'Submitting…':'Submit daily report'"></button></div></form><section class="routine-panel mt-4"><header class="routine-panel-head"><div><h3>Previous reports</h3><p>Your past check-ins and feedback</p></div><span class="routine-count" x-text="`${history.length} reports`"></span></header><template x-for="item in history" :key="item.id"><button @click="openOwnReport(item.id)" class="flex w-full items-center gap-3 border-t border-slate-100 py-3 text-left"><span class="routine-date"><b x-text="new Date(item.report_date).getDate()"></b><small x-text="new Date(item.report_date).toLocaleDateString(undefined,{month:'short'})"></small></span><span class="flex-1"><b class="block text-xs">Daily reflection</b><small class="text-[10px] text-slate-400" x-text="`${item.completion_percentage}% complete · ${item.rating||'—'}/5 rating`"></small></span><span class="routine-status" x-text="item.review_status"></span><span class="text-slate-300">↗</span></button></template><p x-show="!history.length" class="py-5 text-center text-xs text-slate-400">Submitted reports will appear here.</p></section></section>

                    <section x-show="section==='review'&&admin"><div class="routine-heading"><div><small class="routine-eyebrow">ADMIN TOOLS</small><h2>Report review</h2><p>Read reflections and share practical, personal feedback.</p></div></div><section class="routine-panel"><div class="mb-4 grid gap-3 border-b border-slate-100 pb-4 sm:grid-cols-2 xl:grid-cols-[1fr_1fr_1fr_auto]"><label class="routine-filter"><span>PERSON</span><select x-model="filters.user_id" @change="loadReports()"><option value="">All people</option><template x-for="person in users" :key="person.id"><option :value="person.id" x-text="person.name"></option></template></select></label><label class="routine-filter"><span>DATE</span><input type="date" x-model="filters.date" @change="loadReports()"></label><label class="routine-filter"><span>STATUS</span><select x-model="filters.status" @change="loadReports()"><option value="">All statuses</option><option value="pending">Pending</option><option value="reviewed">Reviewed</option></select></label><button class="routine-secondary self-end" @click="filters={user_id:'',date:'',status:''};loadReports()">Clear filters</button></div><div class="overflow-x-auto"><table class="routine-table"><thead><tr><th>PERSON</th><th>DATE</th><th>COMPLETION</th><th>RATING</th><th>STATUS</th><th></th></tr></thead><tbody><template x-for="item in reports" :key="item.id"><tr><td x-text="item.user?.name"></td><td x-text="new Date(item.report_date).toLocaleDateString()"></td><td x-text="`${item.completion_percentage}%`"></td><td class="text-amber-500" x-text="`★ ${item.rating||'—'}/5`"></td><td><span class="routine-status" x-text="item.review_status"></span></td><td><button class="routine-secondary" @click="openReport(item.id)">Review report ↗</button></td></tr></template><tr x-show="!reports.length"><td colspan="6" class="py-7 text-center text-slate-400">No reports match these filters.</td></tr></tbody></table></div></section></section>
                </div>
                <footer class="py-8 text-center text-[10px] text-slate-400">Daywell <span class="mx-1">·</span> A little progress, every day.</footer>
            </div>
        </main>

        <div x-show="report" x-cloak class="routine-backdrop" @click.self="report=null"><section class="routine-modal"><header class="flex justify-between border-b border-slate-100 p-5"><div><small class="routine-eyebrow">DAILY REPORT</small><h2 class="mt-1 font-bold" x-text="`${report?.user?.name||'Your'}'s reflection`"></h2><small class="text-slate-400" x-text="report?new Date(report.report_date).toLocaleDateString():''"></small></div><button @click="report=null">✕</button></header><div class="max-h-[75vh] overflow-y-auto p-5"><div class="grid grid-cols-3 rounded-lg bg-violet-50 p-3 text-center text-xs"><div><small>COMPLETE</small><b class="block" x-text="`${report?.completion_percentage||0}%`"></b></div><div><small>RATING</small><b class="block text-amber-500" x-text="`★ ${report?.rating||'—'}/5`"></b></div><div><small>STATUS</small><b class="block capitalize" x-text="report?.review_status"></b></div></div><h3 class="mt-5 font-bold">Activities</h3><template x-for="activity in report?.activities||[]" :key="activity.id"><div class="mt-2 flex gap-2 rounded border border-slate-100 p-2 text-xs"><span x-text="activity.status==='completed'?'✓':'○'"></span><span class="flex-1" x-text="activity.title"></span><small class="capitalize" x-text="activity.status"></small></div></template><div class="mt-4 grid gap-3 sm:grid-cols-2"><div class="routine-detail sm:col-span-2"><b>Daily work summary</b><p x-text="report?.work_summary||'Not provided.'"></p></div><div class="routine-detail"><b>Challenges</b><p x-text="report?.challenges||'Not provided.'"></p></div><div class="routine-detail"><b>Learning & improvement</b><p x-text="report?.learning||'Not provided.'"></p></div><div class="routine-detail sm:col-span-2"><b>Personal reflection</b><p x-text="report?.reflection||'Not provided.'"></p></div></div><h3 class="mt-5 font-bold">Feedback history</h3><template x-for="f in report?.feedback||[]" :key="f.id"><div class="mt-2 rounded-lg bg-slate-50 p-3 text-xs"><b x-text="f.admin?.name||'Administrator'"></b><small class="float-right text-slate-400" x-text="new Date(f.created_at).toLocaleString()"></small><p class="mt-2" x-text="f.comment"></p><p x-show="f.suggestions" class="mt-1 text-slate-500" x-text="`Suggestion: ${f.suggestions}`"></p></div></template><p x-show="!report?.feedback?.length" class="mt-2 text-xs text-slate-400">No feedback given yet.</p><form x-show="admin" class="mt-5 border-t border-slate-100 pt-4" @submit.prevent="sendFeedback()"><h3 class="mb-3 font-bold">Write feedback</h3><label class="routine-field"><span>Comment</span><textarea rows="3" x-model="feedback.comment" required placeholder="Recognize progress or ask a thoughtful question…"></textarea></label><label class="routine-field mt-3"><span>Improvement suggestions</span><textarea rows="3" x-model="feedback.suggestions" placeholder="Offer one practical next step…"></textarea></label><div class="mt-3 flex justify-between"><button type="button" class="routine-secondary" @click="setStatus(report.review_status==='reviewed'?'pending':'reviewed')" x-text="report.review_status==='reviewed'?'Mark pending':'Mark reviewed'"></button><button class="routine-primary">Send feedback</button></div></form></div></section></div>
        <div x-show="selectedUser" x-cloak class="routine-backdrop" @click.self="selectedUser=null"><section class="routine-modal max-w-xl"><header class="flex justify-between border-b p-5"><div><small class="routine-eyebrow">COMMUNITY MEMBER</small><h2 class="mt-1 font-bold" x-text="selectedUser?.name"></h2><small x-text="selectedUser?.email"></small></div><button @click="selectedUser=null">✕</button></header><div class="p-5"><h3 class="font-bold">Activity summary</h3><div class="mt-3 grid grid-cols-3 gap-2"><div class="routine-detail"><b>Reports</b><p x-text="selectedUser?.activity_summary?.reports||0"></p></div><div class="routine-detail"><b>Avg completion</b><p x-text="`${Math.round(selectedUser?.activity_summary?.average_completion||0)}%`"></p></div><div class="routine-detail"><b>Avg rating</b><p x-text="`${Number(selectedUser?.activity_summary?.average_rating||0).toFixed(1)}/5`"></p></div></div><h3 class="mt-5 font-bold">Recent reports</h3><template x-for="r in selectedUser?.recent_reports||[]" :key="r.id"><div class="mt-2 flex justify-between rounded-lg bg-slate-50 p-3 text-xs"><span x-text="new Date(r.report_date).toLocaleDateString()"></span><span x-text="`${r.completed_activities}/${r.total_activities} activities · ${r.review_status}`"></span></div></template></div></section></div>
        <div x-show="toast" x-cloak class="routine-toast">✓ <span x-text="toast"></span></div>
    </div>
</x-app-layout>
